-- Phase 4A communications: synthetic records, actual client roles, no passwords,
-- tokens, private file bytes or remote connections. Transaction rollback retains
-- production history guards and discards all synthetic activity.
BEGIN;
CREATE TEMP TABLE phase4a_comm_assertions(label text primary key,category text not null) ON COMMIT DROP;
CREATE TEMP TABLE phase4a_comm_results(label text primary key,result jsonb not null) ON COMMIT DROP;
GRANT SELECT,INSERT,UPDATE ON pg_temp.phase4a_comm_assertions,pg_temp.phase4a_comm_results TO authenticated,anon;
CREATE FUNCTION pg_temp.f(label text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$SELECT md5('boss-phase4a-communications:'||label)::uuid$$;
CREATE FUNCTION pg_temp.check(label text,category text,ok boolean) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL [%] %',category,label;END IF;INSERT INTO pg_temp.phase4a_comm_assertions VALUES(label,category);END$$;
CREATE FUNCTION pg_temp.act(label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claim','',true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.f('auth-'||label),'role','authenticated','is_anonymous',false,'session_id',pg_temp.f('session-'||label),'user_metadata',jsonb_build_object('role','platform_administrator'))::text,true);END$$;
CREATE FUNCTION pg_temp.cmd(op text,i jsonb) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_build_object('operation',op,'input',i)$$;
CREATE FUNCTION pg_temp.ok(label text,category text,c jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE r jsonb;BEGIN r:=public.boss_communications_mutate(pg_temp.f('request-'||label),c);PERFORM pg_temp.check(label,category,jsonb_typeof(r)='object');INSERT INTO pg_temp.phase4a_comm_results VALUES(label,r);RETURN r;END$$;
CREATE FUNCTION pg_temp.rid(label text) RETURNS uuid LANGUAGE sql AS $$SELECT (result->>'resource_id')::uuid FROM pg_temp.phase4a_comm_results WHERE phase4a_comm_results.label=$1$$;
CREATE FUNCTION pg_temp.deny(label text,category text,c jsonb,states text[] DEFAULT ARRAY['PT403'],request_label text DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$DECLARE denied boolean:=false;BEGIN BEGIN PERFORM public.boss_communications_mutate(pg_temp.f('request-'||coalesce(request_label,label)),c);EXCEPTION WHEN OTHERS THEN IF SQLSTATE=ANY(states) THEN denied:=true;ELSE RAISE EXCEPTION 'FAIL % unexpected state %: %',label,SQLSTATE,SQLERRM;END IF;END;PERFORM pg_temp.check(label,category,denied);END$$;
CREATE FUNCTION pg_temp.read_deny(label text,q jsonb) RETURNS void LANGUAGE plpgsql AS $$DECLARE denied boolean:=false;BEGIN BEGIN PERFORM public.boss_communications_read(q);EXCEPTION WHEN SQLSTATE 'PT403' THEN denied:=true;END;PERFORM pg_temp.check(label,'ISOLATION',denied);END$$;
CREATE FUNCTION pg_temp.query(thread_label text DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$SELECT jsonb_strip_nulls(jsonb_build_object('organization_id',pg_temp.f('org-a'),'thread_id',CASE WHEN thread_label IS NOT NULL THEN pg_temp.rid(thread_label) END))$$;
CREATE FUNCTION pg_temp.thread(kind text,scope_type text,scope_label text,members jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$SELECT pg_temp.cmd('thread.create',jsonb_strip_nulls(jsonb_build_object('organization_id',pg_temp.f('org-a'),'title','Synthetic controlled '||kind,'kind',kind,'scope_type',scope_type,'scope_id',pg_temp.f(scope_label),'members',members)))$$;
CREATE FUNCTION pg_temp.announcement(target text DEFAULT 'team-a',typ text DEFAULT 'team') RETURNS jsonb LANGUAGE sql AS $$SELECT pg_temp.cmd('announcement.send',jsonb_build_object('organization_id',pg_temp.f('org-a'),'title','Synthetic announcement','body','Synthetic controlled announcement content','targets',jsonb_build_array(jsonb_build_object('scope_type',typ,'scope_id',pg_temp.f(target)))))$$;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure f FROM pg_proc p WHERE p.pronamespace=pg_my_temp_schema() LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.f);EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,anon',f.f);END LOOP;END$$;
-- ACL assertions include the arbitrary-recipient helper boundary.
DO $$DECLARE tab text;f record;BEGIN
 FOREACH tab IN ARRAY ARRAY['communication_threads','communication_thread_members','communication_audiences','communication_messages','communication_message_revisions','communication_read_state','communication_attachments','communication_reports'] LOOP
 PERFORM pg_temp.check(tab||' RLS','SECURITY',(SELECT relrowsecurity FROM pg_class WHERE oid=('public.'||tab)::regclass));
 PERFORM pg_temp.check(tab||' no authenticated raw access','SECURITY',NOT has_table_privilege('authenticated','public.'||tab,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'));
 PERFORM pg_temp.check(tab||' no anon raw access','SECURITY',NOT has_table_privilege('anon','public.'||tab,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'));END LOOP;
 FOR f IN SELECT p.oid::regprocedure id,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='boss_private' AND p.proname IN('comm_person_active','comm_permission','comm_guardian','comm_thread_can_view','comm_message_can_view') LOOP
 PERFORM pg_temp.check(f.proname||' private recipient helper','SECURITY',NOT has_function_privilege('authenticated',f.id,'EXECUTE') AND NOT has_function_privilege('anon',f.id,'EXECUTE'));END LOOP;
 PERFORM pg_temp.check('public RPCs invoker','SECURITY',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname LIKE 'boss_communications_%' AND p.prosecdef));
 PERFORM pg_temp.check('anon RPC closed','SECURITY',NOT has_function_privilege('anon','public.boss_communications_read(jsonb)','EXECUTE') AND NOT has_function_privilege('anon','public.boss_communications_mutate(uuid,jsonb)','EXECUTE'));
END$$;
INSERT INTO auth.users(id,email,email_confirmed_at,is_anonymous) SELECT pg_temp.f('auth-'||p),p||'@phase4a.example.invalid',now()-interval '1 day',false FROM unnest(ARRAY['platform','admin-a','admin-b','coach','assistant','unit','guardian','receive-only','household-only','outsider','child','child2','unknown','expired','finance'])p;
INSERT INTO auth.sessions(id,user_id) SELECT pg_temp.f('session-'||p),pg_temp.f('auth-'||p) FROM unnest(ARRAY['platform','admin-a','admin-b','coach','assistant','unit','guardian','receive-only','household-only','outsider','child','child2','unknown','expired','finance'])p;
INSERT INTO public.people(id,display_name,date_of_birth) SELECT pg_temp.f(p),'Synthetic Phase4A '||p,CASE WHEN p IN('child','child2') THEN current_date-interval '12 years' WHEN p='unknown' THEN NULL ELSE date '1980-01-01' END FROM unnest(ARRAY['platform','admin-a','admin-b','coach','assistant','unit','guardian','receive-only','household-only','outsider','child','child2','unknown','expired','finance'])p;
INSERT INTO public.user_accounts(auth_user_id,person_id,account_status) SELECT pg_temp.f('auth-'||p),pg_temp.f(p),'active' FROM unnest(ARRAY['platform','admin-a','admin-b','coach','assistant','unit','guardian','receive-only','household-only','outsider','child','child2','unknown','expired','finance'])p;
