INSERT INTO public.teams(id,organization_id,parent_unit_id,name,slug) VALUES(pg_temp.f('team-a'),pg_temp.f('org-a'),pg_temp.f('unit-a'),'Synthetic Falcons','a'),(pg_temp.f('team-b'),pg_temp.f('org-a'),pg_temp.f('unit-a'),'Synthetic Owls','b'),(pg_temp.f('team-sibling'),pg_temp.f('org-a'),pg_temp.f('unit-sibling'),'Synthetic sibling','sibling'),(pg_temp.f('team-child'),pg_temp.f('org-a'),pg_temp.f('unit-child'),'Synthetic descendant','child'),(pg_temp.f('other-team'),pg_temp.f('org-b'),NULL,'Synthetic other tenant','other');
UPDATE public.teams SET status='active' WHERE organization_id IN(pg_temp.f('org-a'),pg_temp.f('org-b'));
INSERT INTO public.organization_modules(organization_id,module_id,status,starts_at,configuration) SELECT pg_temp.f(org),m.id,'active',now()-interval '1 day','{"communications":true,"announcements":true,"team_chat":true,"direct_messaging":true,"attachments":true,"moderation":true,"staff_send":false}' FROM public.modules m CROSS JOIN unnest(ARRAY['org-a','org-b'])org WHERE m.key='messaging';
INSERT INTO public.role_assignments(person_id,role_id,scope_type,scope_id,organization_id,starts_at,ends_at)
SELECT pg_temp.f(p),r.id,scope,CASE WHEN target IS NOT NULL THEN pg_temp.f(target) END,CASE WHEN org IS NOT NULL THEN pg_temp.f(org) END,now()-interval '2 days',CASE WHEN p='expired' THEN now()-interval '1 day' END
FROM(VALUES('platform','platform_administrator','platform',NULL,NULL),('admin-a','organization_administrator','organization','org-a','org-a'),('admin-b','organization_administrator','organization','org-b','org-b'),('coach','head_coach','team','team-a','org-a'),('assistant','assistant_coach','team','team-a','org-a'),('unit','program_administrator','organization_unit','unit-a','org-a'),('expired','head_coach','team','team-a','org-a'),('finance','organization_finance','organization','org-a','org-a'))v(p,role,scope,target,org) JOIN public.roles r ON r.key=v.role;
INSERT INTO public.organization_memberships(organization_id,person_id,starts_at) SELECT pg_temp.f('org-a'),pg_temp.f(p),now()-interval '1 day' FROM unnest(ARRAY['admin-a','coach','assistant','unit','guardian','receive-only','household-only','child','child2','unknown','expired','finance'])p;
