INSERT INTO public.team_memberships(organization_id,team_id,person_id,participant_id,membership_type,starts_at) VALUES(pg_temp.f('org-a'),pg_temp.f('team-a'),pg_temp.f('child'),pg_temp.f('participant'),'athlete',now()-interval '1 day'),(pg_temp.f('org-a'),pg_temp.f('team-b'),pg_temp.f('child2'),pg_temp.f('participant2'),'athlete',now()-interval '1 day'),(pg_temp.f('org-a'),pg_temp.f('team-a'),pg_temp.f('unknown'),pg_temp.f('unknown-participant'),'athlete',now()-interval '1 day');
