VALUES(pg_temp.f('guardian-relation'),pg_temp.f('guardian'),pg_temp.f('child'),'active',now()-interval '1 day',now()-interval '1 day',true,true,true),(pg_temp.f('receive-relation'),pg_temp.f('receive-only'),pg_temp.f('child'),'active',now()-interval '1 day',now()-interval '1 day',true,false,true),(pg_temp.f('other-relation'),pg_temp.f('guardian'),pg_temp.f('child2'),'active',now()-interval '1 day',now()-interval '1 day',false,false,true);
