SET LOCAL ROLE authenticated;
SELECT pg_temp.act('admin-a');
SELECT pg_temp.ok('org-announcement','A',pg_temp.announcement('org-a','organization'));
SELECT pg_temp.ok('role-announcement','ROLE-AUDIENCE',pg_temp.cmd('announcement.send',jsonb_build_object('organization_id',pg_temp.f('org-a'),'title','Synthetic coaches only','body','Synthetic exact-role message','targets',jsonb_build_array(jsonb_build_object('scope_type','team','scope_id',pg_temp.f('team-a'),'role_key','head_coach')))));
SELECT pg_temp.deny('role audience incompatible scope','ROLE-AUDIENCE',pg_temp.cmd('announcement.send',jsonb_build_object('organization_id',pg_temp.f('org-a'),'title','Synthetic denied scope','body','Synthetic denied role','targets',jsonb_build_array(jsonb_build_object('scope_type','organization','scope_id',pg_temp.f('org-a'),'role_key','head_coach')))),ARRAY['PT422']);
SELECT pg_temp.ok('team-chat','CHAT',pg_temp.thread('team_chat','team','team-a'));
SELECT pg_temp.ok('other-team-chat','CHAT',pg_temp.thread('team_chat','team','team-b'));
