SELECT pg_temp.ok('first-message','CHAT',pg_temp.cmd('message.send',jsonb_build_object('thread_id',pg_temp.rid('team-chat'),'body','Synthetic message for guardian')));
SELECT pg_temp.ok('multi-team-announcement','J',pg_temp.cmd('announcement.send',jsonb_build_object('organization_id',pg_temp.f('org-a'),'title','Synthetic two-team announcement','body','Synthetic shared announcement','targets',jsonb_build_array(jsonb_build_object('scope_type','team','scope_id',pg_temp.f('team-a')),jsonb_build_object('scope_type','team','scope_id',pg_temp.f('team-b'))))));
SELECT pg_temp.act('coach');
SELECT pg_temp.check('coach exact role audience readable','ROLE-AUDIENCE',jsonb_array_length(public.boss_communications_read(pg_temp.query('role-announcement'))->'detail'->'messages')=1);
